CREATE TABLE locations (id SERIAL PRIMARY KEY, name VARCHAR(255) NOT NULL, location_type VARCHAR(100), latitude DECIMAL(10,8), longitude DECIMAL(11,8), address VARCHAR(500), city VARCHAR(100), emirate VARCHAR(100), description TEXT, opening_hours VARCHAR(255), entry_fee NUMERIC(10,2), created_at TIMESTAMPTZ);
CREATE TABLE routes (id SERIAL PRIMARY KEY, route_name VARCHAR(255), start_location_id INTEGER REFERENCES locations(id), end_location_id INTEGER REFERENCES locations(id), distance_km DECIMAL(8,2), estimated_duration_minutes INTEGER, difficulty_level VARCHAR(50), waypoints JSONB);
CREATE TABLE gps_tracking (id SERIAL PRIMARY KEY, vehicle_id INTEGER, location_id INTEGER REFERENCES locations(id), latitude DECIMAL(10,8), longitude DECIMAL(11,8), speed_kmh DECIMAL(6,2), heading INTEGER, tracked_at TIMESTAMPTZ);
CREATE TABLE geofences (id SERIAL PRIMARY KEY, geofence_name VARCHAR(255), center_latitude DECIMAL(10,8), center_longitude DECIMAL(11,8), radius_meters INTEGER, geofence_type VARCHAR(100), alert_on_enter BOOLEAN, alert_on_exit BOOLEAN);
CREATE TABLE geofence_events (id SERIAL PRIMARY KEY, geofence_id INTEGER REFERENCES geofences(id), vehicle_id INTEGER, event_type VARCHAR(50), event_time TIMESTAMPTZ);
CREATE TABLE poi (id SERIAL PRIMARY KEY, poi_name VARCHAR(255), poi_type VARCHAR(100), latitude DECIMAL(10,8), longitude DECIMAL(11,8), description TEXT, photo_url VARCHAR(500), rating NUMERIC(3,2));
